class_name TestWait
extends RefCounted


func test_wait_command(interpreter: StoryInterpreter) -> bool:
	if not interpreter:
		return false

	var start_time: int = Time.get_ticks_msec()

	await interpreter.execute_command({
		"type": "wait",
		"duration": 0.2
	})

	var elapsed_sec: float = float(Time.get_ticks_msec() - start_time) / 1000.0

	if elapsed_sec < 0.15:
		return false

	if elapsed_sec > 0.45:
		return false

	return true
